import map from "@/data/wp-redirects.json"

/**
 * Old WordPress URLs, answered with a 301 by the Worker (docs/roadmap.md, D6).
 * `_redirects` can't do it: it never applies to Worker responses.
 *
 * The map is generated by the import (`pnpm wp-import:redirects`), never edited
 * by hand. Astro strips a trailing slash with its own 301 before the request
 * reaches here, so `/programandring/` arrives as `/programandring`; both forms
 * are normalised the same way anyway.
 */

const PATHS: Readonly<Record<string, string>> = map.paths
const IDS: Readonly<Record<string, string>> = map.ids

/**
 * Pages the site has moved since the import, kept by hand because the map
 * above is regenerated from the import's cache. Verksamhet and Allmänt were
 * folded into the Klubben page on 2026-10-24 (docs/design.md, "Klubben").
 *
 * Applied to the map's targets as well, so an old WordPress URL that pointed
 * at one of these still arrives in a single hop.
 */
export const MOVED_PAGES: Readonly<Record<string, string>> = {
  "/om-foreningen/verksamhet": "/om-foreningen",
  "/om-foreningen/allmant": "/om-foreningen",
  // Tånnerydsdammen is no lokal of its own; its places are listed on this one.
  "/fagellokaler/tanneryd-damm": "/lokaler/jacobssons-udde",
  // WordPress answered the old address with the post's new slug; article 4929 links to it.
  "/tisdagar-april-maj-motesplats-ekebacken": "/artiklar/tisdagar-april-maj-motesplats-ekebacken-2",
  // The articles' "Program" went on 2026-11-18, so the word means only /kalender;
  // its posts, old excursion announcements, are under Exkursioner. This also
  // carries WordPress's /category/program* there in one hop. It applies only once
  // the category row is gone: until then the category page answers itself.
  "/artiklar/kategori/program": "/artiklar/kategori/exkursioner",
}

const settle = (target: string | undefined): string | null =>
  target === undefined ? null : (MOVED_PAGES[target] ?? target)

/** Decoded, lower-case, without a trailing slash: how the map's keys are stored. */
export function normaliseOldPath(pathname: string): string {
  let path = pathname
  try {
    path = decodeURIComponent(pathname)
  } catch {
    // A malformed escape can't match a key; compare it as it came.
  }
  path = path.toLowerCase()
  return path.length > 1 ? path.replace(/\/+$/, "") : path
}

/**
 * Where an old URL now lives, or null: a WordPress URL from the map, or a page
 * the site itself has moved. `?p=<id>` and `?page_id=<id>` are WordPress's
 * shortlinks, which only ever appear on the home page.
 */
export function wpRedirect(pathname: string, searchParams: URLSearchParams): string | null {
  if (pathname === "/") {
    const id = searchParams.get("p") ?? searchParams.get("page_id")
    return id && /^\d+$/.test(id) ? settle(IDS[id]) : null
  }
  const path = normaliseOldPath(pathname)
  // WordPress paged its lists as <list>/page/<n>: the posts on its home page, a
  // category ("Äldre inlägg" under Program), a month. The site's lists page by
  // keyset, not by number, so each goes to the start of the list it was part of.
  const paged = /^(.*)\/page\/\d+$/.exec(path)
  if (paged) return paged[1] ? wpRedirect(paged[1], searchParams) : "/artiklar"
  const mapped = settle(PATHS[path] ?? MOVED_PAGES[path])
  if (mapped) return mapped
  // WordPress's date archives weren't posts, so the map has no keys for them.
  const archive = /^\/((?:19|20)\d{2})(?:\/\d{1,2}){0,2}$/.exec(path)
  return archive ? `/artiklar/ar/${archive[1]}` : null
}
